import re
import unicodedata


def slugify(text: str, separator: str = "-") -> str:
    plain = "".join(
        char for char in unicodedata.normalize("NFD", text) if not unicodedata.combining(char)
    )
    return separator.join(re.findall(r"[a-z0-9]+", plain.lower()))

